{"type":"assistant","message":{"model":"claude-opus-4-6","id":"msg_01LU9xgUPTnALvMy4c7iZXks","type":"message","role":"assistant","content":[{"type":"tool_use","id":"toolu_01GQzeFXprq3FnTYdmkkmyoc","name":"mcp__agent-ml-research__ssh_execute","input":{"server":"gpu-6000pro-2","command":"cat > /root/autodl-tmp/recursive_gen_depth_est/scripts/detector_baselines/run_all_detectors.py << 'PYEOF'\n\"\"\"\nDetection-based baselines for recursive generation depth estimation.\n\nComputes 5 continuous detection scores on 3x3 grid data, then evaluates\nordinal depth prediction via LR, RF, and quantile binning.\n\nDetectors:\n  1. Binoculars: CE_observer / CE_performer (gpt2-xl / pythia-1.4b)\n  2. Fast-DetectGPT: normalized (token_ll + entropy) discrepancy\n  3. Log-Rank: average log-rank of actual tokens under scoring model\n  4. Entropy: average predictive entropy\n  5. LLR: log-likelihood ratio (ll_observer - ll_performer)\n\nEvaluation:\n  - 5-fold CV Logistic Regression (per-score + combined)\n  - 5-fold CV Random Forest (per-score + combined)\n  - Quantile binning\n  - Pairwise AUC: d0v1, d1v2, d2v3\n\"\"\"\n\nimport argparse\nimport json\nimport os\nimport sys\nimport time\nimport numpy as np\nimport torch\nfrom torch.utils.data import DataLoader, Dataset\nfrom transformers import AutoTokenizer, AutoModelForCausalLM\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.ensemble import RandomForestClassifier\nfrom sklearn.model_selection import StratifiedKFold\nfrom sklearn.metrics import accuracy_score, roc_auc_score\n\nPROJECT_ROOT = \"/root/autodl-tmp/recursive_gen_depth_est\"\n\nGRID_CELLS = {\n    \"pythia_nucleus\": \"data/\",\n    \"pythia_temp09\": \"data/pythia_temp09/\",\n    \"pythia_topk50\": \"data/pythia_topk50/\",\n    \"olmo_nucleus\": \"data/olmo/\",\n    \"olmo_temp09\": \"data/olmo_temp09/\",\n    \"olmo_topk50\": \"data/olmo_topk50/\",\n    \"gpt2xl_nucleus\": \"data/gpt2xl/\",\n    \"gpt2xl_temp09\": \"data/gpt2xl_temp09/\",\n    \"gpt2xl_topk50\": \"data/gpt2xl_topk50/\",\n}\n\nMODEL_PATHS = {\n    \"gpt2xl\": \"/root/autodl-tmp/models/gpt2-xl\",\n    \"pythia\": \"/root/autodl-tmp/models/pythia-1.4b\",\n}\n\nNUM_DEPTHS = 4\nMAX_SEQ_LEN = 512\n\n\nclass TextDataset(Dataset):\n    def __init__(self, texts, tokenizer, max_len=512):\n        self.encodings = tokenizer(\n            texts, max_length=max_len, truncation=True,\n            padding=\"max_length\", return_tensors=\"pt\"\n        )\n\n    def __len__(self):\n        return self.encodings[\"input_ids\"].shape[0]\n\n    def __getitem__(self, idx):\n        return {k: v[idx] for k, v in self.encodings.items()}\n\n\ndef load_cell_data(data_dir, max_per_depth=5000):\n    texts, labels = [], []\n    for d in range(NUM_DEPTHS):\n        fpath = os.path.join(data_dir, f\"depth_{d}.jsonl\")\n        if not os.path.exists(fpath):\n            print(f\"  WARNING: {fpath} not found, skipping depth {d}\")\n            continue\n        count = 0\n        with open(fpath) as f:\n            for line in f:\n                line = line.strip()\n                if not line:\n                    continue\n                rec = json.loads(line)\n                texts.append(rec[\"text\"])\n                labels.append(d)\n                count += 1\n                if count >= max_per_depth:\n                    break\n        print(f\"  depth_{d}: {count} samples\")\n    return texts, np.array(labels)\n\n\n@torch.no_grad()\ndef compute_all_scores(model, tokenizer, texts, device, batch_size=8, label=\"model\"):\n    dataset = TextDataset(texts, tokenizer, MAX_SEQ_LEN)\n    loader = DataLoader(dataset, batch_size=batch_size, shuffle=False)\n\n    all_ll, all_entropy, all_logrank, all_fdgpt = [], [], [], []\n\n    for i, batch in enumerate(loader):\n        input_ids = batch[\"input_ids\"].to(device)\n        attention_mask = batch[\"attention_mask\"].to(device)\n\n        outputs = model(input_ids=input_ids, attention_mask=attention_mask)\n        logits = outputs.logits[:, :-1, :]\n        targets = input_ids[:, 1:]\n        mask = attention_mask[:, 1:].float()\n        lengths = mask.sum(dim=1).clamp(min=1)\n\n        log_probs = torch.log_softmax(logits, dim=-1)\n        probs = torch.softmax(logits, dim=-1)\n\n        # Log-likelihood\n        token_ll = log_probs.gather(2, targets.unsqueeze(-1)).squeeze(-1)\n        token_ll_masked = token_ll * mask\n        mean_ll = token_ll_masked.sum(dim=1) / lengths\n        all_ll.append(mean_ll.cpu().numpy())\n\n        # Entropy\n        entropy = -(probs * log_probs).sum(dim=-1)\n        entropy_masked = entropy * mask\n        mean_entropy = entropy_masked.sum(dim=1) / lengths\n        all_entropy.append(mean_entropy.cpu().numpy())\n\n        # Log-Rank\n        target_probs = probs.gather(2, targets.unsqueeze(-1)).squeeze(-1)\n        ranks = (probs > target_probs.unsqueeze(-1)).sum(dim=-1).float() + 1.0\n        log_ranks = torch.log(ranks)\n        log_ranks_masked = log_ranks * mask\n        mean_logrank = log_ranks_masked.sum(dim=1) / lengths\n        all_logrank.append(mean_logrank.cpu().numpy())\n\n        # Fast-DetectGPT\n        discrepancy = token_ll + entropy\n        discrepancy_masked = discrepancy * mask\n        mean_d = discrepancy_masked.sum(dim=1) / lengths\n        sum_sq = ((discrepancy - mean_d.unsqueeze(1)) ** 2 * mask).sum(dim=1)\n        std_d = (sum_sq / lengths.clamp(min=2)).sqrt().clamp(min=1e-8)\n        fdgpt_score = mean_d / std_d\n        all_fdgpt.append(fdgpt_score.cpu().numpy())\n\n        if (i + 1) % 50 == 0:\n            print(f\"    [{label}] batch {i+1}/{len(loader)}\")\n\n    return {\n        \"ll\": np.concatenate(all_ll),\n        \"entropy\": np.concatenate(all_entropy),\n        \"logrank\": np.concatenate(all_logrank),\n        \"fdgpt\": np.concatenate(all_fdgpt),\n    }\n\n\ndef quantile_binning(scores, labels, n_bins=4):\n    thresholds = np.quantile(scores, [i / n_bins for i in range(1, n_bins)])\n    preds = np.digitize(scores, thresholds)\n    return accuracy_score(labels, preds)\n\n\ndef cv_evaluate(X, labels, clf_factory, n_splits=5, seed=42):\n    skf = StratifiedKFold(n_splits=n_splits, shuffle=True, random_state=seed)\n    accs = []\n    oof_preds = np.zeros_like(labels)\n\n    for train_idx, test_idx in skf.split(X, labels):\n        clf = clf_factory()\n        clf.fit(X[train_idx], labels[train_idx])\n        preds = clf.predict(X[test_idx])\n        oof_preds[test_idx] = preds\n        accs.append(accuracy_score(labels[test_idx], preds))\n\n    return {\n        \"acc_mean\": round(float(np.mean(accs)), 4),\n        \"acc_std\": round(float(np.std(accs)), 4),\n    }\n\n\ndef pairwise_auc(scores, labels, d_low, d_high):\n    mask = (labels == d_low) | (labels == d_high)\n    if mask.sum() < 10:\n        return None\n    y = (labels[mask] == d_high).astype(int)\n    s = scores[mask]\n    try:\n        auc = roc_auc_score(y, s)\n        return round(float(max(auc, 1 - auc)), 4)\n    except ValueError:\n        return None\n\n\ndef score_stats(scores, labels):\n    return {\n        f\"d{d}\": {\"mean\": round(float(scores[labels == d].mean()), 4),\n                   \"std\": round(float(scores[labels == d].std()), 4)}\n        for d in range(NUM_DEPTHS) if (labels == d).sum() > 0\n    }\n\n\ndef evaluate_single_score(name, scores, labels):\n    X = scores.reshape(-1, 1)\n\n    lr_result = cv_evaluate(\n        X, labels,\n        lambda: LogisticRegression(max_iter=1000, random_state=42)\n    )\n    rf_result = cv_evaluate(\n        X, labels,\n        lambda: RandomForestClassifier(n_estimators=100, random_state=42, n_jobs=-1)\n    )\n    bin_acc = quantile_binning(scores, labels)\n\n    aucs = {\n        \"d0v1\": pairwise_auc(scores, labels, 0, 1),\n        \"d1v2\": pairwise_auc(scores, labels, 1, 2),\n        \"d2v3\": pairwise_auc(scores, labels, 2, 3),\n    }\n\n    return {\n        \"lr_acc_mean\": lr_result[\"acc_mean\"],\n        \"lr_acc_std\": lr_result[\"acc_std\"],\n        \"rf_acc_mean\": rf_result[\"acc_mean\"],\n        \"rf_acc_std\": rf_result[\"acc_std\"],\n        \"binning_acc\": round(float(bin_acc), 4),\n        \"pairwise_auc\": aucs,\n        \"score_stats\": score_stats(scores, labels),\n    }\n\n\ndef compute_cell_scores(cell_name, data_dir, model_obs, model_perf,\n                        tok_obs, tok_perf, device, batch_size, cache_dir):\n    \"\"\"Compute raw scores for one cell, with disk caching.\"\"\"\n    cache_path = os.path.join(cache_dir, f\"{cell_name}_scores.npz\")\n    if os.path.exists(cache_path):\n        print(f\"\\n  Loading cached scores for {cell_name}\")\n        data = np.load(cache_path)\n        return {k: data[k] for k in data.files}\n\n    print(f\"\\n{'='*60}\")\n    print(f\"  Computing scores: {cell_name}\")\n    print(f\"{'='*60}\")\n\n    texts, labels = load_cell_data(data_dir)\n    if len(texts) == 0:\n        return None\n    print(f\"  Total: {len(texts)} samples, depths: {np.bincount(labels).tolist()}\")\n\n    t0 = time.time()\n    print(\"  Scoring with observer (gpt2-xl)...\")\n    obs_scores = compute_all_scores(model_obs, tok_obs, texts, device, batch_size, \"gpt2xl\")\n    print(f\"    Done in {time.time()-t0:.1f}s\")\n\n    t1 = time.time()\n    print(\"  Scoring with performer (pythia-1.4b)...\")\n    perf_scores = compute_all_scores(model_perf, tok_perf, texts, device, batch_size, \"pythia\")\n    print(f\"    Done in {time.time()-t1:.1f}s\")\n\n    ce_obs = -obs_scores[\"ll\"]\n    ce_perf = -perf_scores[\"ll\"]\n\n    result = {\n        \"labels\": labels,\n        \"binoculars\": ce_obs / np.clip(ce_perf, 1e-8, None),\n        \"fast_detectgpt\": obs_scores[\"fdgpt\"],\n        \"log_rank\": obs_scores[\"logrank\"],\n        \"entropy\": obs_scores[\"entropy\"],\n        \"llr\": obs_scores[\"ll\"] - perf_scores[\"ll\"],\n    }\n\n    np.savez(cache_path, **result)\n    print(f\"  Cached to {cache_path}\")\n    return result\n\n\ndef evaluate_cell(cell_name, scores_dict):\n    \"\"\"Run all evaluations on precomputed scores.\"\"\"\n    print(f\"\\n  Evaluating: {cell_name}\")\n    labels = scores_dict[\"labels\"]\n    detectors = [\"binoculars\", \"fast_detectgpt\", \"log_rank\", \"entropy\", \"llr\"]\n\n    results = {\"cell\": cell_name, \"n_samples\": len(labels)}\n\n    for det_name in detectors:\n        det_scores = scores_dict[det_name]\n        print(f\"    {det_name}...\", end=\" \", flush=True)\n        results[det_name] = evaluate_single_score(det_name, det_scores, labels)\n        print(f\"LR={results[det_name]['lr_acc_mean']:.4f} RF={results[det_name]['rf_acc_mean']:.4f}\")\n\n    # Combined 5 features\n    X_all = np.column_stack([scores_dict[d] for d in detectors])\n    print(f\"    combined_5feat...\", end=\" \", flush=True)\n    lr_comb = cv_evaluate(X_all, labels,\n                          lambda: LogisticRegression(max_iter=1000, random_state=42))\n    rf_comb = cv_evaluate(X_all, labels,\n                          lambda: RandomForestClassifier(n_estimators=200, random_state=42, n_jobs=-1))\n    results[\"combined_5feat\"] = {\n        \"lr_acc_mean\": lr_comb[\"acc_mean\"], \"lr_acc_std\": lr_comb[\"acc_std\"],\n        \"rf_acc_mean\": rf_comb[\"acc_mean\"], \"rf_acc_std\": rf_comb[\"acc_std\"],\n    }\n    print(f\"LR={lr_comb['acc_mean']:.4f} RF={rf_comb['acc_mean']:.4f}\")\n\n    # Combined 3 core detectors\n    X_3det = np.column_stack([scores_dict[\"binoculars\"], scores_dict[\"fast_detectgpt\"],\n                               scores_dict[\"log_rank\"]])\n    print(f\"    combined_3det...\", end=\" \", flush=True)\n    lr_3 = cv_evaluate(X_3det, labels,\n                       lambda: LogisticRegression(max_iter=1000, random_state=42))\n    rf_3 = cv_evaluate(X_3det, labels,\n                       lambda: RandomForestClassifier(n_estimators=200, random_state=42, n_jobs=-1))\n    results[\"combined_3det\"] = {\n        \"lr_acc_mean\": lr_3[\"acc_mean\"], \"lr_acc_std\": lr_3[\"acc_std\"],